// Application project, which now has a framework reference to ASP.NET Core
public sealed class PlaceOrderHandler(
    IHttpContextAccessor http, IOrderStore orders)
{
    public async Task<IResult> Handle(PlaceOrder cmd, CancellationToken ct)
    {
        // Only an HTTP request can supply this, so a worker can't call it
        var userId = http.HttpContext!.User.FindFirst("sub")!.Value;
        if (cmd.Lines.Count == 0) return Results.BadRequest("Empty order");
        var id = await orders.AddAsync(userId, cmd.Lines, ct);
        return Results.Created($"/orders/{id}", id);
    }
}

// Application: the use case and the port it owns, with no web types
public interface ICurrentUser { string Id { get; } }

public sealed class PlaceOrderHandler(ICurrentUser user, IOrderStore orders)
{
    public async Task<PlaceOrderResult> Handle(
        PlaceOrder cmd, CancellationToken ct)
    {
        if (cmd.Lines.Count == 0)
            return new PlaceOrderResult.Rejected("Empty order");
        var id = await orders.AddAsync(user.Id, cmd.Lines, ct);
        return new PlaceOrderResult.Created(id);
    }
}

// Api: the outer circle implements the inner interface
public sealed class HttpCurrentUser(IHttpContextAccessor http) : ICurrentUser
{
    public string Id => http.HttpContext?.User.FindFirst("sub")?.Value
        ?? throw new InvalidOperationException("No signed-in user");
}
